<?php
declare(strict_types=1);
require_once __DIR__.'/config.php';
require_once __DIR__.'/lib/auth.php';
require_once __DIR__.'/lib/avatar.php';
if(empty($_SESSION['user_id'])){header('Location: /login.php');exit;}
$uid=(int)$_SESSION['user_id'];$currentUser=current_user($pdo);$isAdmin=$currentUser&&(($currentUser['role']??'user')==='admin');
$totalStmt=$pdo->prepare('SELECT COUNT(*) FROM nicknames WHERE user_id=?');$totalStmt->execute([$uid]);$totalCount=(int)$totalStmt->fetchColumn();
$archiveStmt=$pdo->prepare('SELECT COUNT(*) FROM nicknames WHERE user_id=? AND deleted_at IS NOT NULL');$archiveStmt->execute([$uid]);$archiveCount=(int)$archiveStmt->fetchColumn();
$draftStmt=$pdo->prepare('SELECT id,title,slug,description,avatar_path FROM nicknames WHERE user_id=? AND deleted_at IS NULL AND is_published=0 ORDER BY created_at DESC');$draftStmt->execute([$uid]);$cabinetClicuhas=$draftStmt->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="<?=h($lang)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h(t('cabinet.title'))?> · Clicuha</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="/assets/css/sema.css?v=125"><style>body{background:#f4f5f9}.cab-wrapper{padding:2.5rem 0 3rem}.cab-card{border-radius:18px;border:1px solid rgba(0,0,0,.05);box-shadow:0 8px 20px rgba(15,23,42,.04);background:#fff;height:100%}.cab-card-dark{background:#050816;color:#f9fafb;border:none}.cab-card-dark h5,.cab-card-dark p{color:#f9fafb}.cab-sidebar-title{font-weight:600;font-size:1.05rem;margin-bottom:.75rem}.clicuha-room{border:1px solid rgba(0,0,0,.07);border-radius:14px;padding:12px;background:#fafafa}.clicuha-room-avatar{width:52px;height:52px;border-radius:12px;object-fit:cover;background:#ececf1}.clicuha-room-empty{width:52px;height:52px;border-radius:12px;background:#ececf1;display:grid;place-items:center;font-weight:700;color:#777}</style></head><body><?php require __DIR__.'/partials/navbar.php';?><main class="cab-wrapper"><div class="container"><?php if(isset($_GET['deleted'])&&$_GET['deleted']==='1'):?><div class="alert alert-success"><?=h(t('cabinet.archived'))?></div><?php endif;?><div class="row g-4"><div class="col-12 col-md-3"><aside class="cab-card p-4 h-100"><div class="cab-sidebar-title"><?=h(t('cabinet.manage'))?></div><ul class="list-unstyled mb-0"><li class="mb-2"><a href="/my_nicknames.php" class="link-dark text-decoration-none">• <?=h(t('cabinet.my'))?> <span class="badge text-bg-secondary ms-1"><?=$totalCount?></span></a></li><li class="mb-2"><a href="/add_bootstrap.php" class="link-dark text-decoration-none">• <?=h(t('cabinet.create'))?></a></li><?php if($isAdmin):?><li class="mb-2"><a href="/admin/" class="link-dark text-decoration-none fw-semibold">• Адмінка</a></li><?php endif;?><li class="mb-2"><span class="text-secondary">• <?=h(t('cabinet.settings'))?></span></li><li><span class="text-secondary">• <?=h(t('cabinet.theme'))?></span></li></ul></aside></div><div class="col-12 col-md-3"><section class="cab-card p-4 h-100"><h5 class="mb-3">У кабінеті <?php if($cabinetClicuhas):?><span class="badge text-bg-secondary"><?=count($cabinetClicuhas)?></span><?php endif;?></h5><?php if(!$cabinetClicuhas):?><p class="text-secondary small mb-3">Тут з’являться клікухи, які ти ще не опублікував.</p><a href="/add_bootstrap.php" class="btn btn-sm btn-primary">+ Нова Clicuha</a><?php else:?><div class="d-flex flex-column gap-3"><?php foreach($cabinetClicuhas as $n):$avatar=clicuha_avatar_url($n['avatar_path']??null);$initial=mb_strtoupper(mb_substr(trim((string)$n['title']),0,1,'UTF-8'),'UTF-8');if($initial==='')$initial='C';?><div class="clicuha-room"><div class="d-flex gap-2 align-items-center"><?php if($avatar):?><img class="clicuha-room-avatar" src="<?=h($avatar)?>" alt="<?=h($n['title'])?>"><?php else:?><div class="clicuha-room-empty"><?=h($initial)?></div><?php endif;?><div class="min-w-0"><div class="fw-semibold"><?=h($n['title'])?></div><?php if($n['slug']):?><div class="small text-secondary">@<?=h($n['slug'])?></div><?php endif;?></div></div><div class="d-flex gap-2 mt-3"><a href="/edit_nickname.php?id=<?=(int)$n['id']?>" class="btn btn-sm btn-outline-primary">Зайти</a></div></div><?php endforeach;?></div><a href="/add_bootstrap.php" class="btn btn-sm btn-primary mt-3">+ Нова Clicuha</a><?php endif;?></section></div><div class="col-12 col-md-3"><section class="cab-card p-4 mb-4"><h5 class="mb-3 text-center"><?=h(t('cabinet.activity'))?></h5><p class="mb-3"><?=h(t('cabinet.activity_text'))?></p><div class="text-center"><a href="/my_nicknames.php" class="btn btn-outline-primary">Всі мої клікухи</a></div></section><section class="cab-card p-4"><h5 class="mb-2"><?=h(t('cabinet.archive'))?> <?php if($archiveCount):?><span class="badge text-bg-secondary"><?=$archiveCount?></span><?php endif;?></h5><p class="mb-3"><?=h(t('cabinet.archive_text'))?></p><a href="/my_archive.php" class="btn btn-sm btn-outline-secondary">Відкрити архів</a></section></div><div class="col-12 col-md-3"><section class="cab-card cab-card-dark p-4 h-100"><h5 class="mb-3"><?=h(t('cabinet.ads'))?></h5><p class="mb-0"><?=h(t('cabinet.ads_text'))?></p></section></div></div></div></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>